use serde_json::{json,Value};
use sha2::{Digest,Sha256};
use std::{fs,path::{Path,PathBuf},collections::{BTreeMap,BTreeSet}};
const R:&str="/home/ubuntu/src/zopro-perf-work/epoch-clock176";
fn r(s:impl AsRef<Path>)->PathBuf{Path::new(R).join(s)}
fn load(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn med(mut x:Vec<u64>)->u64{x.sort_unstable();x[x.len()/2]}
fn close(a:f64,b:f64){assert!((a-b).abs()<=1e-12*a.abs().max(b.abs()).max(1.));}
fn main(){
 let a=load(r("analysis.json"));let mut pins=0;for f in["native-pins.json","pins.json"]{for(p,h)in load(r(f)).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());pins+=1;}}
 let mut commands=0;for dir in["native","runs"]{let plan=load(r(if dir=="native"{"native-plan.json"}else{"plan.json"}));let result=load(r(format!("{dir}/result.json")));assert_eq!(result["status"],"complete");for s in plan["steps"].as_array().unwrap(){let n=s["name"].as_str().unwrap();let e=load(r(format!("{dir}/{n}/exit.json")));assert_eq!(e["returncode"],0);assert_eq!(e["success"],true);for stream in["stdout","stderr"]{assert_eq!(hash(r(format!("{dir}/{n}/{stream}.log"))),e[format!("{stream}_sha256")]);}commands+=1;}}
 assert_eq!(commands,400);for arm in["OFF","ON"]{for(s,n)in[("core",128),("prover",2),("cubic",6)]{let t=load(r(format!("native/{s}-{arm}/tests.json")));assert_eq!(t["passed_tests"].as_array().unwrap().len(),n);assert_eq!(t["unfiltered"],true);}}
 let manifest=load("/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-30-g2-vector-sign-adoption176/artifacts/production-source-manifest.json");let audit=load(r("source-audit.json"));let mut exact=0;
 for(p,h)in manifest["source_files_sha256"].as_object().unwrap(){assert_eq!(hash(Path::new("/home/ubuntu/src/zk-tools/zopro").join(p)),h.as_str().unwrap());let b=fs::read(r(format!("source/{p}"))).unwrap();if format!("{:x}",Sha256::digest(&b))==h.as_str().unwrap(){exact+=1;continue;}let mut s=String::from_utf8(b).unwrap();if p=="crates/zopro-core/src/lib.rs"{s=s.strip_suffix(audit["lib_suffix"].as_str().unwrap()).unwrap().to_string();}else{assert_eq!(p,"crates/zopro-core/src/solver.rs");for e in audit["edits"].as_array().unwrap().iter().rev(){let before=e[0].as_str().unwrap();let after=e[1].as_str().unwrap();assert_eq!(s.matches(after).count(),1);s=s.replacen(after,before,1);}}assert_eq!(format!("{:x}",Sha256::digest(s.as_bytes())),h.as_str().unwrap());}assert_eq!(exact,174);
 let jobs=load(r("jobs.json"));let mut ledger=load(r("prior-proof-sha256.json")).as_array().unwrap().iter().map(|v|v.as_str().unwrap().to_string()).collect::<BTreeSet<_>>();assert_eq!(ledger.len(),29255);
 let mut calls=0;let mut snapshots=0;let mut cells=BTreeMap::<String,Vec<(usize,u64)>>::new();let mut epochs=BTreeMap::<String,Vec<Vec<u64>>>::new();let mut exports=0;
 for j in jobs.as_array().unwrap(){let name=j["name"].as_str().unwrap();let ctx=j["case"]["name"].as_str().unwrap();let arm=j["arm"].as_str().unwrap();let text=fs::read_to_string(r(format!("runs/{name}/stdout.log"))).unwrap();let records=|tag:&str|text.lines().filter_map(|l|l.strip_prefix(tag)).map(|s|serde_json::from_str::<Value>(s).unwrap()).collect::<Vec<_>>();let ss=records("SAMPLE ");let ee=records("EPOCH ");let sm=records("SUMMARY ");assert_eq!(sm.len(),1);assert_eq!(sm[0]["workers"],j["case"]["workers"]);assert_eq!(sm[0]["priming"],3);let n=j["rounds"].as_u64().unwrap()as usize;assert_eq!(ss.len(),n);assert_eq!(ee.len(),if arm=="ON"{n}else{0});calls+=n+3;snapshots+=ee.len();let mut ns=Vec::new();for(i,v)in ss.iter().enumerate(){assert_eq!(v["round"],i);let x=v["ms"].as_f64().unwrap()*1e6;let q=x.round()as u64;assert!(q>0&&(x-q as f64).abs()<1e-5);ns.push(q);}
 for(i,v)in ee.iter().enumerate(){assert_eq!(v["round"],i);assert_eq!(v["expected_epochs"],16);assert_eq!(v["ops"],if ctx.starts_with("1x2"){31061}else{54083});assert_eq!(v["kind"],0);assert_eq!(v["complete"],true);let t=v["elapsed_ns"].as_array().unwrap().iter().map(|x|x.as_u64().unwrap()).collect::<Vec<_>>();assert_eq!(t.len(),17);assert_eq!(t[0],0);assert!(t.windows(2).all(|x|x[0]<=x[1]));assert!(t[16]<=ns[i]);if j["phase"]=="latency"{epochs.entry(ctx.into()).or_default().push(t);}}
 if j["phase"]=="latency"{cells.entry(format!("{ctx}/{arm}")).or_default().push((j["block"].as_u64().unwrap()as usize,med(ns)));}
 let dir=Path::new(j["proof_directory"].as_str().unwrap());assert_eq!(fs::metadata(dir.join("0.proof")).unwrap().len(),164);let ph=hash(dir.join("0.proof"));let wh=hash(dir.join("0.public"));assert!(ledger.insert(ph.clone()));assert_eq!(wh,j["case"]["public_sha256"]);let output=fs::read_to_string(r(format!("runs/verify-{name}/stdout.log"))).unwrap();let lines=output.lines().filter(|l|l.starts_with("VERIFIED ")).collect::<Vec<_>>();assert_eq!(lines.len(),1);let fields=lines[0].split_whitespace().skip(1).map(|s|s.split_once('=').unwrap()).collect::<BTreeMap<_,_>>();assert_eq!(fields["proof_sha256"],ph);assert_eq!(fields["public_sha256"],wh);assert_eq!(fields["image_sha256"],j["case"]["image_sha256"].as_str().unwrap());assert_eq!(fields["vk_sha256"],j["case"]["vk_sha256"].as_str().unwrap());exports+=1;
 }
 assert_eq!((calls,snapshots,exports,ledger.len()),(6168,1864,192,29447));let after=load(r("proof-sha256-after.json")).as_array().unwrap().iter().map(|v|v.as_str().unwrap().to_string()).collect::<BTreeSet<_>>();assert_eq!(ledger,after);
 let mut failed=Vec::new();for ctx in["1x2-w16","1x2-w32","2x2-w16","2x2-w32"]{for arm in["accepted","OFF","ON"]{let key=format!("{ctx}/{arm}");let c=cells.get_mut(&key).unwrap();c.sort_unstable();assert_eq!(c.len(),15);assert!(c.iter().enumerate().all(|(i,x)|i==x.0));close(med(c.iter().map(|x|x.1).collect())as f64/1e6,a["cells"][&key]["median_ms"].as_f64().unwrap());}
 for(x,y)in[("OFF","accepted"),("ON","OFF"),("ON","accepted")]{let key=format!("{ctx}/{x}/{y}");let ratios=(0..15).map(|i|cells[&format!("{ctx}/{x}")][i].1 as f64/cells[&format!("{ctx}/{y}")][i].1 as f64).collect::<Vec<_>>();for(i,v)in ratios.iter().enumerate(){close(*v,a["pairs"][&key]["ratios"][i].as_f64().unwrap());}let mut sorted=ratios;sorted.sort_by(f64::total_cmp);for(k,i)in[("low",3),("median",7),("high",11)]{close(sorted[i],a["pairs"][&key][k].as_f64().unwrap());}let ok=sorted[11]<=1.03&&(x!="OFF"||sorted[3]>=1./1.03);assert_eq!(a["checks"][&key],ok);if !ok{failed.push(key);}}
 let e=&epochs[ctx];assert_eq!(e.len(),465);for stage in 0..17{let s=&a["epoch_timing"][ctx]["stage_descriptive_stats"][stage];let cumul=e.iter().map(|t|t[stage]).collect::<Vec<_>>();let remain=e.iter().map(|t|t[16]-t[stage]).collect::<Vec<_>>();assert_eq!(s["cumulative_median_ns"].as_f64().unwrap(),med(cumul.clone())as f64);assert_eq!(s["cumulative_min_ns"].as_f64().unwrap(),*cumul.iter().min().unwrap()as f64);assert_eq!(s["cumulative_max_ns"].as_f64().unwrap(),*cumul.iter().max().unwrap()as f64);assert_eq!(s["remaining_solver_median_ns"].as_f64().unwrap(),med(remain)as f64);}}
 failed.sort();assert_eq!(json!(failed),a["failed_checks"]);assert_eq!(a["observer_overhead_screen_passed"],false);
 for shape in["1x2","2x2"]{let x=load(r(format!("{shape}-w16-readiness.json")));let y=load(format!("/home/ubuntu/src/zopro-perf-work/parallel-readiness176/{shape}.json"));assert_eq!(x["query_results"],y["query_results"]);let read=|p:PathBuf|fs::read(p).unwrap().chunks_exact(8).map(|b|u64::from_le_bytes(b.try_into().unwrap())).collect::<Vec<_>>();let x=read(r(format!("{shape}-w16.schedule.bin")));let y=read(PathBuf::from(format!("/home/ubuntu/src/zopro-perf-work/parallel-readiness176/{shape}.schedule.bin")));assert_eq!(x.len(),y.len());assert!(x[15..].chunks_exact(5).zip(y[15..].chunks_exact(5)).all(|(x,y)|x[0]==y[0]));}
 let v=json!({"passed":true,"pins_checked":pins,"successful_commands":commands,"originals_recovered":176,"originals_exact":174,"production_unchanged":true,"raw_integer_ns_reconstruction":true,"epoch_marks_and_all_declared_gates_recomputed":true,"SDK_requests":calls,"clock_snapshots":snapshots,"fresh_Gnark_exports":exports,"proof_ledger":ledger.len(),"observer_overhead_screen_passed":false,"failed_checks":failed,"adopted":false});fs::write(r("review.json"),serde_json::to_vec_pretty(&v).unwrap()).unwrap();println!("{v}");
}
